import{_ as n,a0 as a,w as r,s as d,ao as p,I as i,x as e,a1 as o,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"跟蹤多個 Git 遠程倉庫 | LCTT x X-CMD","titleTemplate":false,"description":"跟蹤多個 Git 遠程倉庫 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"跟蹤多個 Git 遠程倉庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"跟蹤多個 Git 遠程倉庫 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201125 Keep track of multiple Git remote repositories","title":"跟蹤多個 Git 遠程倉庫","tag":"202012","desc":""},"relativePath":"202012/20201125 Keep track of multiple Git remote repositories.md","filePath":"[post].md"}'),u={name:"202012/20201125 Keep track of multiple Git remote repositories.md"};function g(m,t,b,k,f,h){const s=a("Link");return r(),d("div",null,[t[30]||(t[30]=p('<h1 id="跟蹤多個-git-遠程倉庫" tabindex="-1">跟蹤多個 Git 遠程倉庫 <a class="header-anchor" href="#跟蹤多個-git-遠程倉庫" aria-label="Permalink to “跟蹤多個 Git 遠程倉庫”">​</a></h1><blockquote><p>擁有一致的命名標準是保持本地和上游 Git 倉庫保持一致的關鍵。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/11/220828tjt9qlpmg1opvibq.jpg" alt=""></p><p>當本地 Git 倉庫的命名與遠程倉庫不一致時，與遠程倉庫協作就會變得很混亂。</p><p>解決此問題的一個方法是標準化兩個詞的使用和含義：<code>origin</code> 指的是你個人的 <code>example.com/&lt;USER&gt;/*</code> 倉庫，而 <code>upstream</code> 指的是你從 <code>origin</code> 倉庫<ruby>復刻<rt>fork</rt></ruby>出來的 <code>example.com</code> 倉庫。換句話説，<code>upstream</code> 指的是公開提交工作的上游倉庫，而 <code>origin</code> 指的是你對上游倉庫的本地復刻，例如，你從這裏生成<ruby>拉取請求<rt>pull request</rt></ruby>（PR）。</p>',5)),i("p",null,[t[1]||(t[1]=e("以 ",-1)),o(s,{href:"https://github.com/distributed-system-analysis/pbench"},{default:l(()=>[...t[0]||(t[0]=[e("pbench",-1)])]),_:1}),t[2]||(t[2]=e(" 倉庫為例，下面是一個逐步建立新的本地克隆的方法，其中 ",-1)),t[3]||(t[3]=i("code",null,"origin",-1)),t[4]||(t[4]=e(" 和 ",-1)),t[5]||(t[5]=i("code",null,"upstream",-1)),t[6]||(t[6]=e(" 的定義是一致的。",-1))]),t[31]||(t[31]=i("p",null,"1、在大多數 Git 託管服務上，當你想在上面工作時，必須對它進行復刻。當你運行自己的 Git 服務器時，這並不是必要的，但對於一個公開的代碼庫來説，這是一個在貢獻者之間傳輸差異的簡單方法。",-1)),t[32]||(t[32]=i("p",null,[e("創建一個 Git 倉庫的復刻。在這個例子中，假設你的復刻位於 "),i("code",null,"example.com/<USER>/pbench"),e("。")],-1)),i("p",null,[t[8]||(t[8]=e("2、接下來，你必須獲得一個統一資源標識符 （",-1)),o(s,{href:"https://en.wikipedia.org/wiki/Uniform_Resource_Identifier"},{default:l(()=>[...t[7]||(t[7]=[e("URI",-1)])]),_:1}),t[9]||(t[9]=e("），以便通過 SSH 進行",-1)),t[10]||(t[10]=i("ruby",null,[e("克隆"),i("rt",null,"cloning")],-1)),t[11]||(t[11]=e("。在大多數 Git 託管服務上，比如 GitLab 或 GitHub，它在一個標有 “Clone” 或 “Clone over SSH” 的按鈕或面板上，可以將克隆 URI 複製到剪貼板中。",-1))]),t[33]||(t[33]=p(`<p>3、在你的開發系統中，使用你複製的 URI 克隆倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone git@example.com:&lt;USER&gt;/pbench.git</span></span></code></pre></div><p>這將以默認名稱 <code>origin</code> 來克隆 Git 倉庫，作為你的 <code>pbench</code> 倉庫復刻副本。</p><p>4、切換到剛才克隆的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/pbench</span></span></code></pre></div><p>5、下一步，獲取源倉庫的 SSH URI（你最初復刻的那個）。這可能和上面的方法一樣。找到 “Clone” 按鈕或面板，複製克隆地址。在軟件開發中，這通常被稱為“上游”，因為（理論上）這是大多數提交發生的地方，而你打算讓這些提交流向下游的倉庫。</p><p>6、將 URI 添加到你的本地倉庫中。是的，將有<em>兩個不同</em>的遠程倉庫分配給你的本地倉庫副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote add upstream git@example.com:bigproject/pbench.git</span></span></code></pre></div><p>7、現在你有兩個命名遠程倉庫：<code>origin</code> 和 <code>upstream</code>。 你可以用 <code>remote</code> 子命令查看你的遠程倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote -v</span></span></code></pre></div><p>現在，你的本地 <code>master</code> 分支正在跟蹤 <code>origin</code> 的 <code>master</code>，這不一定是你想要的。你可能想跟蹤這個分支的 <code>upstream</code> 版本，因為大多數開發都在上游進行。這個想法是，你要在從上游獲得的內容的基礎上添加更改。</p><p>8、將你的本地的 <code>master</code> 分支改成跟蹤 <code>upstream/master</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git fetch upstream</span></span>
<span class="line"><span>$ git branch --set-upstream-to=upstream/master master</span></span></code></pre></div><p>你可以對任何你想要的分支這樣做，而不僅僅是 <code>master</code>。例如，有些項目使用 <code>dev</code> 分支來處理所有不穩定的變化，而將 <code>master</code> 保留給已批准發佈的代碼。</p><p>9、一旦你設置了你的跟蹤分支，一定要變基（<code>rebase</code>）你的 <code>master</code> 分支，使它與上游倉庫的任何新變化保持一致：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote update</span></span>
<span class="line"><span>$ git checkout master</span></span>
<span class="line"><span>$ git rebase</span></span></code></pre></div>`,16)),i("p",null,[t[13]||(t[13]=e("這是一個保持 Git 倉庫在不同復刻之間同步的好方法。如果你想自動完成這項工作，請閲讀 Seth Kenlon 關於",-1)),o(s,{href:"https://opensource.com/article/19/11/how-host-github-gitlab-ansible"},{default:l(()=>[...t[12]||(t[12]=[e("使用 Ansible 託管 Git 倉庫",-1)])]),_:1}),t[14]||(t[14]=e("的文章。",-1))]),t[34]||(t[34]=i("hr",null,null,-1)),i("p",null,[t[16]||(t[16]=e("via: ",-1)),o(s,{href:"https://opensource.com/article/20/11/multiple-git-repositories"},{default:l(()=>[...t[15]||(t[15]=[e("https://opensource.com/article/20/11/multiple-git-repositories",-1)])]),_:1})]),i("p",null,[t[21]||(t[21]=e("作者：",-1)),o(s,{href:"https://opensource.com/users/portante"},{default:l(()=>[...t[17]||(t[17]=[e("Peter Portante",-1)])]),_:1}),t[22]||(t[22]=e(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[18]||(t[18]=[e("lujun9972",-1)])]),_:1}),t[23]||(t[23]=e(" 譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[19]||(t[19]=[e("geekpi",-1)])]),_:1}),t[24]||(t[24]=e(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[20]||(t[20]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[27]||(t[27]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[25]||(t[25]=[e("LCTT",-1)])]),_:1}),t[28]||(t[28]=e(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:l(()=>[...t[26]||(t[26]=[e("Linux中國",-1)])]),_:1}),t[29]||(t[29]=e(" 榮譽推出",-1))])])}const y=n(u,[["render",g]]);export{T as __pageData,y as default};
